import React, { useState, useEffect, useMemo } from "react";
import { attendanceAPI } from "./api_service";

const COLORS = {
  primary: "#4F46E5",
  primaryLight: "#EEF2FF",
  success: "#10B981",
  successLight: "#DCFCE7",
  danger: "#EF4444",
  dangerLight: "#FEE2E2",
  warning: "#F59E0B",
  warningLight: "#FEF3C7",
  textMain: "#1E293B",
  textMuted: "#64748B",
  border: "#E2E8F0",
  background: "#F8FAFC",
  surface: "#FFFFFF"
};

const Dashboard = () => {

  // ================= SAFE FUNCTION =================
  const safe = (val) => {
    if (val === null || val === undefined) return "—";
    if (typeof val === "object") {
      if (val.name) return val.name;
      if (val.first_name || val.last_name)
        return `${val.first_name || ""} ${val.last_name || ""}`.trim();
      return JSON.stringify(val);
    }
    return val;
  };

  const safeNumber = (val) => {
    const num = Number(val);
    return isNaN(num) ? 0 : num;
  };

  // ================= STATES =================
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    summary: {
      unique_students: 0,
      total_records: 0,
      avg_confidence: 0,
      max_confidence: 0,
      min_confidence: 0
    }
  });

  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [autoRefresh, setAutoRefresh] = useState(false);
  const [lastUpdated, setLastUpdated] = useState(new Date());

  // ================= LOAD DATA =================
  const loadData = async () => {
    try {
      if (attendanceLog.length === 0) setLoading(true);

      const [statsRes, logRes, statusRes] = await Promise.all([
        attendanceAPI.getStats(),
        attendanceAPI.getTodayLog(),
        attendanceAPI.getStatus()
      ]);

      const dataStats = statsRes?.data || {};
      const summary = dataStats.summary || {};

      setStats({
        active_students: safeNumber(dataStats.active_students),
        present_today: safeNumber(dataStats.present_today),
        absent_today: safeNumber(dataStats.absent_today),
        summary: {
          unique_students: safeNumber(summary.unique_students),
          total_records: safeNumber(summary.total_records),
          avg_confidence: safeNumber(summary.avg_confidence),
          max_confidence: safeNumber(summary.max_confidence),
          min_confidence: safeNumber(summary.min_confidence)
        }
      });

      setAttendanceLog(Array.isArray(logRes?.data?.records) ? logRes.data.records : []);
      setStatusList(Array.isArray(statusRes?.data?.students) ? statusRes.data.students : []);

      setLastUpdated(new Date());
      setError(null);

    } catch (err) {
      console.error(err);
      setError("Erreur serveur ou API indisponible");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    let timer;
    if (autoRefresh) {
      timer = setInterval(loadData, 10000);
    }
    return () => clearInterval(timer);
  }, [autoRefresh]);

  // ================= CARDS =================
  const statCards = useMemo(() => {
    const total = stats.active_students;
    const present = stats.present_today;
    const rate = total > 0 ? Math.round((present / total) * 100) : 0;

    return [
      { id: "total", label: "Étudiants", value: total, color: COLORS.primary },
      { id: "present", label: "Présents", value: present, color: COLORS.success },
      { id: "absent", label: "Absents", value: stats.absent_today, color: COLORS.danger },
      { id: "rate", label: "Taux", value: `${rate}%`, color: "#8B5CF6" }
    ];
  }, [stats]);

  // ================= LOADING =================
  if (loading) {
    return <div style={{ padding: 40 }}>Chargement...</div>;
  }

  return (
    <div style={{ padding: 30 }}>

      <h2>Dashboard</h2>
      <p>Mis à jour : {lastUpdated.toLocaleTimeString()}</p>

      {error && <div style={{ color: "red" }}>{error}</div>}

      {/* STATS */}
      <div style={{ display: "flex", gap: 20 }}>
        {statCards.map(card => (
          <div key={card.id} style={{
            padding: 20,
            border: "1px solid #ddd",
            borderRadius: 10
          }}>
            <div>{card.label}</div>
            <strong>{card.value}</strong>
          </div>
        ))}
      </div>

      {/* TABLE LOG */}
      <h3 style={{ marginTop: 30 }}>Logs</h3>

      <table border="1" cellPadding="10">
        <thead>
          <tr>
            <th>Étudiant</th>
            <th>Temps</th>
            <th>Confiance</th>
          </tr>
        </thead>
        <tbody>
          {attendanceLog.length > 0 ? attendanceLog.map((row, i) => (
            <tr key={i}>
              <td>{safe(row.student)}</td>

              <td>
                {typeof row.timestamp === "object"
                  ? new Date(row.timestamp).toLocaleTimeString()
                  : safe(row.timestamp)}
              </td>

              <td>
                {safeNumber(row.confidence) > 0
                  ? (safeNumber(row.confidence) * 100).toFixed(1) + "%"
                  : "—"}
              </td>
            </tr>
          )) : (
            <tr>
              <td colSpan="3">Aucune donnée</td>
            </tr>
          )}
        </tbody>
      </table>

      {/* STATUS */}
      <h3 style={{ marginTop: 30 }}>Statut classe</h3>

      <table border="1" cellPadding="10">
        <thead>
          <tr>
            <th>Nom</th>
            <th>Email</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {statusList.map((student, i) => (
            <tr key={i}>
              <td>{safe(student.name)}</td>
              <td>{safe(student.email)}</td>
              <td>{student.present ? "Présent" : "Absent"}</td>
            </tr>
          ))}
        </tbody>
      </table>

    </div>
  );
};

export default Dashboard;
